import { useState, useEffect } from 'react';
import { Link, useLocation } from 'wouter';
import { useFirebaseAuth } from '@/auth/AuthProvider';
import { useQuery } from '@tanstack/react-query';
import { Badge } from '@/components/ui/badge';
import { FollowUsBar } from '@/components/FollowUsBar';
import { Button } from '@/components/ui/button';
import {
  Home, Briefcase, CalendarDays, Wallet, User,
  Bell, Settings, FileText, Shield, Bot,
  Menu, X, ChevronRight, Power, LogOut,
  Dog, MapPin, Car, GraduationCap, Star,
  DollarSign, ClipboardList, ShieldCheck, ThumbsUp, TrendingUp, Crown,
} from 'lucide-react';
import POSDashboard from './POSDashboard';
import POSJobs from './POSJobs';
import POSCalendar from './POSCalendar';
import POSWallet from './POSWallet';
import POSProfile from './POSProfile';
import POSSettings from './POSSettings';
import POSDocuments from './POSDocuments';
import POSNotifications from './POSNotifications';
import POSSafety from './POSSafety';
import POSAssistant from './POSAssistant';
import POSServices from './POSServices';

type Module = 'dashboard' | 'jobs' | 'calendar' | 'wallet' | 'profile' | 'services' | 'settings' | 'documents' | 'notifications' | 'safety' | 'assistant';
// Providers serve exactly the SaaS service platforms — PetSitter, Walk My Pet,
// Academy (+ PetTrek, coming soon). NO K9000 wash: the wash is PetWash Ltd
// in-house staff, not a provider/contractor service.
type Platform = 'all' | 'petsitter' | 'walkpet' | 'academy' | 'pettrek';

const PLATFORMS: { id: Platform; label: string; labelHe: string; icon: React.ComponentType<any>; soon?: boolean }[] = [
  { id: 'all', label: 'All Services', labelHe: 'כל השירותים', icon: Dog },
  { id: 'petsitter', label: 'PetSitter', labelHe: 'PetSitter', icon: Dog },
  { id: 'walkpet', label: 'Walk My Pet', labelHe: 'Walk My Pet', icon: MapPin },
  { id: 'academy', label: 'Academy', labelHe: 'Academy', icon: GraduationCap },
  { id: 'pettrek', label: 'PetTrek', labelHe: 'PetTrek', icon: Car, soon: true },
];

const BOTTOM_NAV = [
  { id: 'dashboard' as Module, label: 'Home', labelHe: 'בית', icon: Home },
  { id: 'jobs' as Module, label: 'Jobs', labelHe: 'עבודות', icon: Briefcase },
  { id: 'calendar' as Module, label: 'Calendar', labelHe: 'יומן', icon: CalendarDays },
  { id: 'wallet' as Module, label: 'Wallet', labelHe: 'ארנק', icon: Wallet },
];

const SIDEBAR_ITEMS = [
  { id: 'dashboard' as Module, label: 'Dashboard', labelHe: 'דשבורד', icon: Home },
  { id: 'jobs' as Module, label: 'Jobs & Bookings', labelHe: 'עבודות והזמנות', icon: Briefcase },
  { id: 'calendar' as Module, label: 'Calendar & Availability', labelHe: 'יומן וזמינות', icon: CalendarDays },
  { id: 'wallet' as Module, label: 'Wallet & Payouts', labelHe: 'ארנק ותשלומים', icon: Wallet },
  { id: 'profile' as Module, label: 'Provider Profile', labelHe: 'פרופיל ספק', icon: User },
  { id: 'services' as Module, label: 'Services & Add-ons', labelHe: 'שירותים ותוספות', icon: Star },
  { id: 'settings' as Module, label: 'Settings', labelHe: 'הגדרות', icon: Settings },
  { id: 'documents' as Module, label: 'Documents', labelHe: 'מסמכים', icon: FileText },
  { id: 'notifications' as Module, label: 'Notifications', labelHe: 'התראות', icon: Bell },
  { id: 'safety' as Module, label: 'Safety & Reporting', labelHe: 'בטיחות ודיווח', icon: Shield },
  { id: 'assistant' as Module, label: 'AI Assistant', labelHe: 'עוזר AI', icon: Bot },
];

/** Links to full standalone pages that are already built but were previously hidden */
const SIDEBAR_LINKS = [
  { href: '/provider/tasks',      label: 'Task Inbox',   labelHe: 'תיבת משימות', icon: ClipboardList },
  { href: '/provider/earnings',   label: 'Earnings',     labelHe: 'הכנסות',      icon: DollarSign },
  { href: '/provider-compliance', label: 'Compliance',   labelHe: 'ציות',        icon: ShieldCheck },
  { href: '/provider/feedback',   label: 'Feedback',     labelHe: 'משוב',        icon: ThumbsUp },
  { href: '/provider/ranking',    label: 'My Ranking',   labelHe: 'דירוג שלי',   icon: TrendingUp },
];

const MODULE_LABELS: Record<Module, string> = {
  dashboard: 'Dashboard', jobs: 'Jobs & Bookings', calendar: 'Calendar & Availability',
  wallet: 'Wallet & Payouts', profile: 'Provider Profile', services: 'Services & Add-ons',
  settings: 'Settings', documents: 'Documents & Signatures', notifications: 'Notifications',
  safety: 'Safety & Reporting', assistant: 'AI Assistant',
};

export default function ProviderOS() {
  // Deep-link support: /provider-os?m=jobs opens that module directly (used by the
  // provider bottom nav so its tabs land on the right module, not a dead route).
  const [activeModule, setActiveModule] = useState<Module>(() => {
    if (typeof window !== 'undefined') {
      const m = new URLSearchParams(window.location.search).get('m');
      if (m && m in MODULE_LABELS) return m as Module;
    }
    return 'dashboard';
  });
  const [activePlatform, setActivePlatform] = useState<Platform>('all');
  const [moreMenuOpen, setMoreMenuOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isAvailable, setIsAvailable] = useState(true);
  const { user, logout } = useFirebaseAuth();

  // Real unread notification count from API
  const { data: notifications } = useQuery<any[]>({
    queryKey: ['/api/notifications'],
    queryFn: () => fetch('/api/notifications', { credentials: 'include' }).then(r => r.json()),
    staleTime: 30_000,
    select: (data: any) => (Array.isArray(data?.notifications) ? data.notifications : Array.isArray(data) ? data : []),
  });
  const unreadCount = Array.isArray(notifications) ? notifications.filter((n: any) => !n.isRead).length : 0;

  // Provider availability — read the REAL state + PERSIST toggles (2026-07-09 fix).
  // The header Available/Offline toggle previously only flipped local state and
  // never saved, so a provider who tapped "Offline" was still shown available to
  // customers and it reverted on refresh. providerId + the true isAvailable come
  // from the same stats payload the dashboard already uses.
  const { data: provStats } = useQuery<any>({
    queryKey: ['/api/provider-dashboard/v2/stats'],
    queryFn: () => fetch('/api/provider-dashboard/v2/stats', { credentials: 'include' }).then(r => r.json()),
    staleTime: 30_000,
  });
  const providerId: number | undefined = provStats?.platforms?.[0]?.id;
  useEffect(() => {
    const serverAvail = provStats?.platforms?.[0]?.isAvailable;
    if (typeof serverAvail === 'boolean') setIsAvailable(serverAvail);
  }, [provStats]);

  const persistAvailability = async (next: boolean) => {
    setIsAvailable(next); // optimistic
    if (!providerId) return;
    try {
      const r = await fetch('/api/provider-dashboard/availability', {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ providerId, isAvailable: next }),
      });
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
    } catch {
      setIsAvailable(!next); // revert on failure — never leave a lying toggle
    }
  };

  // Router navigation (distinct from `navigate` below, which switches the
  // in-shell provider module). Used by the "Switch to Member" bridge so an
  // approved provider — who is ALSO always a member — can jump to their
  // customer/member world instead of being trapped inside provider-os.
  const [, setRoute] = useLocation();

  const navigate = (mod: Module) => {
    setActiveModule(mod);
    setMoreMenuOpen(false);
    setSidebarOpen(false);
    window.scrollTo(0, 0);
  };

  const displayName = user?.displayName || user?.email?.split('@')[0] || 'Provider';

  return (
    <div className="min-h-screen bg-white flex flex-col" style={{ fontFamily: "'Inter', system-ui, sans-serif" }}>
      {/* Brand crown + utility bar — sticky together */}
      <div className="sticky top-0 z-40 bg-white border-b border-gray-200">
      {/* Real PetWash™ logo, top-center crown (brand rule: never recreate, always centered) */}
      <div className="flex flex-col items-center pt-2 pb-1.5">
        <img src="/brand/petwash-logo-official.png" alt="PetWash" className="h-6 object-contain" loading="eager" />
        <span className="text-[8px] tracking-[0.3em] text-[#9a8a5c] mt-0.5">PROVIDER</span>
      </div>
      <header className="h-14 flex items-center px-4 gap-3 border-t border-gray-50">
        <button
          className="lg:hidden p-1.5 rounded-md text-gray-500 hover:bg-gray-50 transition-colors"
          onClick={() => setSidebarOpen(true)}
        >
          <Menu className="w-5 h-5" />
        </button>

        <div className="flex-1 overflow-x-auto">
          <div className="flex gap-1 min-w-max">
            {PLATFORMS.map(p => {
              const Icon = p.icon;
              if (p.soon) {
                return (
                  <span
                    key={p.id}
                    className="px-2.5 py-1 rounded-full text-xs font-medium whitespace-nowrap flex items-center gap-1 border border-dashed border-gray-300 text-gray-400"
                    title="Coming soon"
                  >
                    <Icon className="w-3 h-3" />
                    {p.label}
                    <span className="text-[9px] uppercase tracking-wide">· soon</span>
                  </span>
                );
              }
              return (
                <button
                  key={p.id}
                  onClick={() => setActivePlatform(p.id)}
                  className={`px-2.5 py-1 rounded-full text-xs font-medium transition-all whitespace-nowrap flex items-center gap-1 ${
                    activePlatform === p.id
                      ? 'bg-[#D4AF37] text-white'
                      : 'bg-white text-gray-600 hover:bg-gray-50'
                  }`}
                >
                  <Icon className="w-3 h-3" />
                  {p.label}
                </button>
              );
            })}
          </div>
        </div>

        <div className="flex items-center gap-2 shrink-0">
          <button
            onClick={() => persistAvailability(!isAvailable)}
            className={`flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium transition-colors ${
              isAvailable ? 'bg-green-100 text-green-700' : 'bg-white text-gray-500'
            }`}
          >
            <Power className="w-3 h-3" />
            <span className="hidden sm:block">{isAvailable ? 'Available' : 'Offline'}</span>
          </button>

          {/* Switch to Member world — the persistent one-tap bridge back to the
              customer side (book, wash, wallet, rewards). A PetWash account is a
              SET of roles (CEO 2026-07-03): a provider is ALWAYS also a member,
              so this is always offered. Mirrors the full ExperienceSwitcher —
              which was mounted ONLY on /my-account and so invisible from here —
              as an Uber-style mode switch so an approved provider is never
              trapped in provider-os with no way back to their member home. */}
          <button
            onClick={() => setRoute('/prestige/home')}
            className="flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium bg-[#FBF6E7] text-[#9a7d2e] border border-[#ECDFB4] hover:bg-[#F5EAC8] transition-colors"
            data-testid="switch-to-member"
            title="Switch to your Member world"
          >
            <Crown className="w-3 h-3" />
            <span className="hidden sm:block">Member</span>
          </button>

          <button
            onClick={() => navigate('notifications')}
            className="relative p-1.5 text-gray-500 hover:bg-white rounded-md transition-colors"
          >
            <Bell className="w-5 h-5" />
            {unreadCount > 0 && (
              <span className="absolute -top-0.5 -right-0.5 bg-red-500 text-white text-[9px] font-bold rounded-full min-w-[14px] h-[14px] flex items-center justify-center px-0.5">
                {unreadCount}
              </span>
            )}
          </button>

          {/* Was a dead <div> (a real dead-click on the account avatar). Now a
              button to the account hub, where the full ExperienceSwitcher +
              settings live. */}
          <button
            onClick={() => setRoute('/my-account')}
            className="w-7 h-7 rounded-full bg-[#FBF6E7] border border-[#ECDFB4] flex items-center justify-center text-[#9a7d2e] text-xs font-semibold hover:ring-2 hover:ring-[#ECDFB4] transition-shadow"
            data-testid="provider-account"
            title="Account & settings"
          >
            {displayName.charAt(0).toUpperCase()}
          </button>
        </div>
      </header>
      </div>

      <div className="flex flex-1 overflow-hidden">
        {/* Desktop sidebar */}
        <aside className="hidden lg:flex flex-col w-56 bg-white border-r border-gray-200 shrink-0">
          <div className="px-4 py-4 border-b border-gray-100">
            <p className="text-xs text-gray-500">Signed in as</p>
            <p className="text-sm font-medium text-gray-900 truncate">{displayName}</p>
          </div>
          <nav className="flex-1 py-3 px-2 overflow-y-auto">
            {SIDEBAR_ITEMS.map(item => {
              const Icon = item.icon;
              const isActive = activeModule === item.id;
              return (
                <button
                  key={item.id}
                  onClick={() => navigate(item.id)}
                  className={`w-full flex items-center gap-2.5 px-3 py-2 rounded-lg text-sm font-medium transition-all mb-0.5 ${
                    isActive
                      ? 'bg-[#FBF6E7] text-[#9a7d2e]'
                      : 'text-gray-600 hover:bg-white hover:text-gray-900'
                  }`}
                >
                  <Icon className={`w-4 h-4 shrink-0 `} />
                  <span className="truncate">{item.label}</span>
                  {item.id === 'notifications' && unreadCount > 0 && (
                    <span className="ms-auto bg-red-500 text-white text-[9px] font-bold rounded-full min-w-[16px] h-4 flex items-center justify-center px-1">
                      {unreadCount}
                    </span>
                  )}
                </button>
              );
            })}
            {/* Hidden-gem pages — already built, now surfaced */}
            <div className="mt-3 pt-3 border-t border-gray-100">
              <p className="px-3 mb-1 text-[10px] font-semibold text-gray-400 uppercase tracking-wider">Analytics</p>
              {SIDEBAR_LINKS.map(link => {
                const Icon = link.icon;
                return (
                  <Link key={link.href} href={link.href}>
                    <a className="w-full flex items-center gap-2.5 px-3 py-2 rounded-lg text-sm font-medium text-gray-600 hover:bg-white hover:text-gray-900 transition-all mb-0.5">
                      <Icon className="w-4 h-4 shrink-0" />
                      <span className="truncate">{link.label}</span>
                    </a>
                  </Link>
                );
              })}
            </div>
          </nav>
          <div className="px-4 py-3 border-t border-gray-100">
            <button
              type="button"
              onClick={() => logout()}
              className="flex items-center gap-2 text-xs text-gray-400 hover:text-gray-600 transition-colors"
              data-testid="button-provideros-logout"
            >
              <LogOut className="w-3.5 h-3.5" />
              Log out
            </button>
          </div>
        </aside>

        {/* Mobile drawer */}
        {sidebarOpen && (
          <div className="fixed inset-0 z-50 lg:hidden">
            <div className="absolute inset-0 bg-black/40" onClick={() => setSidebarOpen(false)} />
            <aside className="absolute start-0 top-0 bottom-0 w-64 bg-white shadow-xl flex flex-col">
              <div className="flex items-center justify-between px-4 py-4 border-b border-gray-100">
                <div>
                  <p className="text-xs text-gray-500">Provider OS</p>
                  <p className="text-sm font-semibold text-gray-900 truncate">{displayName}</p>
                </div>
                <button onClick={() => setSidebarOpen(false)} className="p-1.5 rounded-md hover:bg-white">
                  <X className="w-5 h-5 text-gray-500" />
                </button>
              </div>
              <nav className="flex-1 py-3 px-2 overflow-y-auto">
                {SIDEBAR_ITEMS.map(item => {
                  const Icon = item.icon;
                  const isActive = activeModule === item.id;
                  return (
                    <button
                      key={item.id}
                      onClick={() => navigate(item.id)}
                      className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm font-medium transition-all mb-0.5 ${
                        isActive ? 'bg-[#FBF6E7] text-[#9a7d2e]' : 'text-gray-700 hover:bg-white'
                      }`}
                    >
                      <Icon className={`w-4 h-4 shrink-0 `} />
                      {item.label}
                      {item.id === 'notifications' && unreadCount > 0 && (
                        <span className="ms-auto bg-red-500 text-white text-[9px] font-bold rounded-full min-w-[16px] h-4 flex items-center justify-center px-1">
                          {unreadCount}
                        </span>
                      )}
                    </button>
                  );
                })}
                {/* Hidden-gem pages — already built, now surfaced */}
                <div className="mt-3 pt-3 border-t border-gray-100">
                  <p className="px-3 mb-1 text-[10px] font-semibold text-gray-400 uppercase tracking-wider">Analytics</p>
                  {SIDEBAR_LINKS.map(link => {
                    const Icon = link.icon;
                    return (
                      <Link key={link.href} href={link.href}>
                        <a
                          onClick={() => setSidebarOpen(false)}
                          className="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm font-medium text-gray-700 hover:bg-white transition-all mb-0.5"
                        >
                          <Icon className="w-4 h-4 shrink-0" />
                          {link.label}
                        </a>
                      </Link>
                    );
                  })}
                </div>
              </nav>
              <div className="px-4 py-3 border-t border-gray-100">
                <button
                  type="button"
                  onClick={() => logout()}
                  className="flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700"
                  data-testid="button-provideros-logout-mobile"
                >
                  <LogOut className="w-4 h-4" /> Log out
                </button>
              </div>
            </aside>
          </div>
        )}

        {/* Main content */}
        <main className="flex-1 overflow-y-auto pb-24 lg:pb-0">
          <div className="px-4 py-4 lg:px-6 max-w-5xl mx-auto">
            <div className="mb-4 lg:hidden">
              <h1 className="text-lg font-semibold text-gray-900">{MODULE_LABELS[activeModule]}</h1>
            </div>
            {activeModule === 'dashboard' && <POSDashboard activePlatform={activePlatform} isAvailable={isAvailable} onToggleAvailable={setIsAvailable} onNavigate={navigate} />}
            {activeModule === 'jobs' && <POSJobs activePlatform={activePlatform} />}
            {activeModule === 'calendar' && <POSCalendar />}
            {activeModule === 'wallet' && <POSWallet activePlatform={activePlatform} />}
            {activeModule === 'profile' && <POSProfile />}
            {activeModule === 'services' && <POSServices />}
            {activeModule === 'settings' && <POSSettings />}
            {activeModule === 'documents' && <POSDocuments />}
            {activeModule === 'notifications' && <POSNotifications />}
            {activeModule === 'safety' && <POSSafety />}
            {activeModule === 'assistant' && <POSAssistant />}
            <FollowUsBar />
          </div>
        </main>
      </div>

      {/* Mobile bottom nav */}
      <nav className="lg:hidden fixed bottom-0 inset-x-0 bg-white border-t border-gray-200 z-40 safe-area-pb">
        <div className="flex items-stretch h-16">
          {BOTTOM_NAV.map(item => {
            const Icon = item.icon;
            const isActive = activeModule === item.id;
            return (
              <button
                key={item.id}
                onClick={() => navigate(item.id)}
                className="flex-1 flex flex-col items-center justify-center gap-0.5 transition-colors touch-manipulation"
              >
                <Icon className={`w-5 h-5 ${isActive ? 'text-[#D4AF37]' : 'text-gray-400'}`} />
                <span className={`text-[10px] font-medium ${isActive ? 'text-[#D4AF37]' : 'text-gray-400'}`}>
                  {item.label}
                </span>
              </button>
            );
          })}
          <button
            onClick={() => setMoreMenuOpen(!moreMenuOpen)}
            className="flex-1 flex flex-col items-center justify-center gap-0.5 touch-manipulation"
          >
            <Menu className="w-5 h-5 text-gray-400" />
            <span className="text-[10px] font-medium text-gray-400">More</span>
          </button>
        </div>
      </nav>

      {/* Mobile "More" menu */}
      {moreMenuOpen && (
        <div className="fixed inset-0 z-50 lg:hidden" onClick={() => setMoreMenuOpen(false)}>
          <div className="absolute inset-0 bg-black/40" />
          <div className="absolute bottom-16 inset-x-0 bg-white border-t border-gray-200 rounded-t-2xl shadow-xl" onClick={e => e.stopPropagation()}>
            <div className="p-2 pt-3">
              <div className="w-10 h-1 rounded-full bg-gray-300 mx-auto mb-4" />
              <div className="grid grid-cols-3 gap-1">
                {SIDEBAR_ITEMS.filter(i => !BOTTOM_NAV.find(b => b.id === i.id)).map(item => {
                  const Icon = item.icon;
                  const isActive = activeModule === item.id;
                  return (
                    <button
                      key={item.id}
                      onClick={() => navigate(item.id)}
                      className={`flex flex-col items-center gap-1.5 p-3 rounded-xl transition-colors touch-manipulation ${
                        isActive ? 'bg-[#FBF6E7]' : 'hover:bg-gray-50'
                      }`}
                    >
                      <Icon className={`w-5 h-5 ${isActive ? 'text-[#D4AF37]' : 'text-gray-600'}`} />
                      <span className={`text-[10px] font-medium text-center leading-tight ${isActive ? 'text-[#9a7d2e]' : 'text-gray-600'}`}>
                        {item.label}
                      </span>
                    </button>
                  );
                })}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
